songs_to_remove = {}  # song_id -> list of playlist_ids
for sid, song_str in song_details.items():
    if song_str in old_songs_set:
        print(f"MATCH: {sid} -> {song_str}")
        songs_to_remove[sid] = []
        for p in playlists:
